// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./multiowner-base.sol";
import "./inamespace-manager.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

contract NamespaceManager is Initializable, UUPSUpgradeable, MultiOwnerBase, INamespaceManager {
    /// @custom:storage-location erc7201:dtn.core.namespacemanager.001
    struct NamespaceManagerStorageV001 {
        mapping(bytes32 => NamespaceConfig) namespaces;
    }

    // keccak256(abi.encode(uint256(keccak256("dtn.core.namespacemanager.001")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant NamespaceManagerStorageV001Location = 0xa1a8a1e2cb6009f225580651017bd88c470975b96e9e7869a2efeb9cc01cfd00;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        // _disableInitializers();
    }

    function initialize(address _owner) public initializer {
        __NamespaceManager_init(_owner);
    }

    function __NamespaceManager_init(address _owner) internal onlyInitializing {
        __MultiOwnerBase_init(_owner);

        _registerNamespace("model.system", address(0));
        _registerNamespace("node.system", address(0));
        _registerNamespace("trust.system", address(0));
        _registerNamespace("api.system", address(0));
    }

    function __NamespaceManager_init_unchained() internal onlyInitializing {
    }

    /// @dev Returns the storage struct for this contract
    function _getStorage() internal pure returns (NamespaceManagerStorageV001 storage $) {
        assembly {
            $.slot := NamespaceManagerStorageV001Location
        }
    }

    /// @inheritdoc INamespaceManager
    function getNamespaceOwner(bytes32 namespaceId) external view override returns (address) {
        NamespaceManagerStorageV001 storage $ = _getStorage();
        return $.namespaces[namespaceId].owner;
    }

    /// @inheritdoc INamespaceManager
    function registerNamespace(string memory namespace, address owner) external override onlyDtn {
        require(owner != address(0), "NamespaceManager: zero address owner");
        NamespaceManagerStorageV001 storage $ = _getStorage();
        bytes32 namespaceId = keccak256(abi.encodePacked(namespace));
        require($.namespaces[namespaceId].owner == address(0), "NamespaceManager: namespace already exists");

        $.namespaces[namespaceId] = NamespaceConfig({
            owner: owner,
            namespaceId: namespaceId,
            namespace: namespace // Namespace string is not stored to save gas
        });

            emit NamespaceRegistered(namespace, namespaceId, owner);
    }

    function _registerNamespace(string memory namespace, address owner) internal {
        NamespaceManagerStorageV001 storage $ = _getStorage();
        bytes32 namespaceId = keccak256(abi.encodePacked(namespace));
        require($.namespaces[namespaceId].owner == address(0), "NamespaceManager: namespace already exists");

        $.namespaces[namespaceId] = NamespaceConfig({
            owner: owner,
            namespaceId: namespaceId,
            namespace: namespace // Namespace string is not stored to save gas
        });
        emit NamespaceRegistered(namespace, namespaceId, owner);
    }

    /// @dev Event emitted when a new namespace is registered
    event NamespaceRegistered(string indexed namespace, bytes32 indexed namespaceId, address indexed owner);

    function _authorizeUpgrade(address newImplementation) internal onlyOwner virtual override {
    }
}

contracts/model/imodel-manager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title IModelManager
 * @notice Interface for managing AI models and their namespaces
 */
interface IModelManager {
    /// Events
    event ModelNamespaceRegistered(string namespace, address owner);
    event ModelAPIRegistered(string namespace, string api, string docs);
    event ModelRegistered(string namespace, string modelName, bytes32 modelId);

    /// Errors
    error NamespaceNotFound(string namespace);
    error NamespaceAlreadyExists(string namespace);
    error UnauthorizedNamespaceAccess(string namespace);
    error InvalidModelName(string modelName);

    /// @notice Struct to store model API configuration
    struct ModelApi {
        bytes32 apiNamespaceId;
        string apiName;
        bytes32 apiId;
        string specs;
        string docs;
    }

    /// @notice Struct to store model serving configuration
    struct ModelConfig {
        bytes32 modelNamespaceId; // The namespace id of the model group
        bytes32 modelId;
        bytes32 modelApiId;
        string modelName;
    }

    /// @notice Register a model API for a namespace
    /// @param namespace The namespace the API belongs to
    /// @param apiName The API name
    /// @param specs The API specification
    /// @param docs Documentation for the API
    function registerModelAPI(string memory namespace, string memory apiName, string memory specs, string memory docs) external;

    /// @notice Register a new model in a namespace
    /// @param namespace The namespace to register the model in
    /// @param modelName The name of the model
    /// @param modelApi The API of the model
    /// @return modelId The unique identifier for the model
    function registerModel(string memory namespace, string memory modelName, string memory modelApi) external returns (bytes32);

    /// @notice Get the model API configuration
    /// @param apiId The unique identifier for the model API
    /// @return modelApi The model API configuration
    function getModelAPI(bytes32 apiId) external view returns (ModelApi memory);

    /// @notice Get the model configuration
    /// @param modelId The unique identifier for the model
    /// @return modelConfig The model configuration
    function getModelConfig(bytes32 modelId) external view returns (ModelConfig memory);

    /// @notice Check if a model exists
    /// @param modelId The unique identifier for the model
    /// @return exists True if the model exists, false otherwise
    function modelExists(bytes32 modelId) external view returns (bool);
}

contracts/node/inode-manager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "../core/dtn.sol";
import "../model/imodel-manager.sol";

/**
 * @title INodeManager
 * @notice Interface for node management in the DeepTrust Network
 */
interface INodeManager {
    /// @notice Struct to store node details
    struct Node {
        address owner;           // Address of the node owner
        address staker;          // Address of the node staker
        address worker;          // Address of the node worker
        bytes32[] trustNamespaces; // List of namespaces supported by the node
        uint256[] trustNamespaceExpirations; // List of namespace expiration times
        bytes32 nodeNamespaceId; // Node namespace ID
        bool isActive;           // Node activation status
        uint256 stakedAmount;    // Amount staked by the node
        bytes32 id;              // Node ID
    }

    /// @notice Flattened node data for external returns
    struct NodeData {
        address owner;
        address staker;
        address worker;
        bytes32[] trustNamespaces;
        uint256[] trustNamespaceExpirations;
        bytes32 nodeNamespaceId;
        bool isActive;
        uint256 stakedAmount;
        bytes32 id;
    }

    /// @notice Emitted when a new user is registered
    event UserRegistered(bytes32 indexed userId, address indexed owner, address staker);

    /// @notice Emitted when a new node is registered
    event NodeRegistered(bytes32 indexed nodeId, address indexed staker, address worker);

    /// @notice Emitted when a node's status is updated
    event NodeStatusUpdated(bytes32 indexed nodeId, bool isActive);

    /// @notice Emitted when node namespaces are updated
    event NodeNamespacesUpdated(bytes32 indexed nodeId, string[] namespaces);

    /// @notice Emitted when node models are updated
    event NodeModelsUpdated(bytes32 indexed nodeId, bytes32[] modelIds);

    /// @notice Emitted when node scores are updated
    event NodeScoresUpdated(
        bytes32 indexed nodeId, 
        uint256 responseRate, 
        uint256 validAnswerRate, 
        uint256 complainRate
    );

    /**
     * @notice Register a new user. It will also register three namespaces:
     * "node.userid", "model.node.userid", "api.node.userid"
     * @param namespace The namespace of the user
     * @param staker The address of the staker
     */
    function registerUser(
        string memory namespace,
        address staker
    ) external;

    /// @notice Register a new node
    function registerNode(
        string memory username,
        string memory nodeName,
        address worker
    ) external payable;

    /**
     * @notice Update node namespaces. Namespace owners must sign the namespaces.
     * For example, if a node is part of a proprietory trusted group, the group
     * owner will sign the namespaces.
     * @param nodeId The node id
     * @param namespaces The namespaces to update
     * @param namespaceSignatures The signatures of the namespaces
     */
    function updateNodeNamespaces(
        bytes32 nodeId,
        string[] calldata namespaces,
        uint256[] calldata namespaceExpirations,
        bytes[] calldata namespaceSignatures
    ) external;

    /// @notice Set models served by the node
    function setNodeModels(bytes32 nodeId, bytes32[] calldata modelIds) external;

    /// @notice Get node details
    function getNode(bytes32 nodeId) external view returns (NodeData memory);

    /// @notice Get node models configuration
    function getNodeModels(bytes32 nodeId) external view returns (bytes32[] memory);

    /// @notice Get all nodes serving a specific model
    function getNodesServingModel(bytes32 modelId) external view returns (bytes32[] memory);

    /// @notice Remove models from a node
    function removeModelsFromNode(bytes32 nodeId, bytes32[] calldata modelIds) external;

    /// @notice Set node active status
    function setNodeStatus(bytes32 nodeId, bool isActive) external;

    /// @notice Check if a node has a specific trust namespace
    function nodeHasTrustNamespace(bytes32 nodeId, bytes32 namespaceId) external view returns (bool);

    /// @notice Get the expiration time for a node's trust namespace
    function nodeTrustNamespaceExpiration(bytes32 nodeId, bytes32 namespaceId) external view returns (uint256);

    /// @notice Check if a node serves a specific model
    function nodeServesModel(bytes32 nodeId, bytes32 modelId) external view returns (bool);
}

